"""J11 author self-checks; no production or independent QA claim."""
from pathlib import Path
import hashlib,json,subprocess,unittest
ROOT=Path(__file__).resolve().parents[1];NODE=ROOT.parent/'runtime/node/bin/node'
class J11PMTest(unittest.TestCase):
 def node(self,s):
  r=subprocess.run([str(NODE),'--input-type=module','-e',s],cwd=ROOT,text=True,capture_output=True);self.assertEqual(r.returncode,0,r.stdout+r.stderr)
 def test_original_intent_statistics_and_revocation(self):
  self.node("""import assert from 'node:assert/strict';import {Model} from './demo/journeys/j11/model.mjs';const m=new Model();const old=m.exportTicket();m.next='unknown';assert.equal(m.save('test','Synthetic test account'),true);assert.equal(m.status,'UNKNOWN');assert.equal(m.canRead(),false);assert.equal(m.readTicket(old.id),null);assert.equal(m.exportTicket(),null);assert.equal(m.submissions,1);assert.equal(m.save('test','duplicate'),false);assert.equal(m.lookup(),true);assert.equal(m.status,'PENDING');m.runStats('failure');assert.equal(m.status,'FAILED');assert.equal(m.canRead(),false);m.runStats();assert.equal(m.status,'READY');assert.equal(m.submissions,1);assert.equal(m.statsAttempts,2);assert.equal(m.summary().present,6);let ticket=m.exportTicket();let csv=m.readTicket(ticket.id);assert.match(csv,/SYN-C2/);m.revoke();assert.equal(m.readTicket(ticket.id),null);m.refresh();assert.equal(m.canRead(),true);assert.equal(m.readTicket(ticket.id),null);m.next='conflict';assert.equal(m.save('regular','Restore checked value'),false);assert.equal(m.classification,'staff');assert.match(m.error,/409/);m.role='analyst';assert.equal(m.save('regular','No access'),false);assert.equal(m.audit.length,1);""")
 def test_dom_unknown_failed_ready_and_old_export(self):
  self.node("""import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {JSDOM} from 'jsdom';const dom=new JSDOM(readFileSync('./demo/journeys/j11/index.html','utf8'),{runScripts:'dangerously',url:'file:///p/index.html'});const d=dom.window.document,c=s=>{assert.ok(d.querySelector(s),s);d.querySelector(s).click()},set=(id,value,type='change')=>{d.getElementById(id).value=value;d.getElementById(id).dispatchEvent(new dom.window.Event(type,{bubbles:true}))};c('[data-act="export"]');set('next','unknown');set('reason','Synthetic reviewer account','input');d.getElementById('classify').dispatchEvent(new dom.window.Event('submit',{bubbles:true,cancelable:true}));assert.match(d.querySelector('.badge').textContent,/UNKNOWN/);assert.equal(d.querySelector('[data-act="export"]'),null);c('[data-act="lookup"]');c('[data-act="stats-fail"]');assert.match(d.querySelector('.badge').textContent,/FAILED/);c('[data-act="stats"]');assert.match(d.querySelector('#result').textContent,/SYN-C2/);c('[data-act="export"]');c('[data-ticket="EXP-2"]');assert.match(d.querySelector('#csv-result').textContent,/SYN-C2/);c('[data-act="revoke"]');c('[data-ticket="EXP-2"]');assert.match(d.querySelector('main').textContent,/410/);c('[data-act="refresh"]');c('[data-ticket="EXP-2"]');assert.match(d.querySelector('main').textContent,/失效|revoked/);assert.equal(dom.window.pm.submissions,1);dom.window.close();""")
 def test_self_contained_manifest(self):
  html=(ROOT/'demo/journeys/j11/index.html').read_text();model=(ROOT/'demo/journeys/j11/model.mjs').read_text().split('\nexport { Model };')[0];self.assertIn(model,html);self.assertNotIn('<script src=',html);self.assertNotIn('fetch(',html)
  for p,h in json.loads((ROOT/'docs/product/journeys/j11/artifact-manifest.json').read_text())['files'].items():self.assertEqual(hashlib.sha256((ROOT/p).read_bytes()).hexdigest(),h,p)
